/*
 * ESP32 Preferences — store and retrieve settings
 *
 * The simulator keeps Preferences values in memory for this page load.
 * They do not survive a page refresh like real ESP32 NVS storage.
 */
#include <Preferences.h>

Preferences preferences;

void setup() {
  Serial.begin(115200);

  if (!preferences.begin("settings", false)) {
    Serial.println("Could not open Preferences");
    return;
  }

  preferences.putInt("bootCount", 7);
  preferences.putBool("enabled", true);
  preferences.putString("deviceName", "ArduSim ESP32");

  Serial.println("Saved settings:");
  Serial.print("Boot count: ");
  Serial.println(preferences.getInt("bootCount", 0));
  Serial.print("Enabled: ");
  Serial.println(preferences.getBool("enabled", false) ? "yes" : "no");
  Serial.print("Device: ");
  Serial.println(preferences.getString("deviceName", "unknown"));
  Serial.print("Stored keys: ");
  Serial.println(preferences.isKey("bootCount") ? "bootCount found" : "missing");

  preferences.end();
}

void loop() {
  delay(1000);
}
